18	    const match = titleStr.match(/第(.+?)[章节]/);
19	    if (match) {
20	        const numStr = match[1];
21	        if (!isNaN(numStr)) return parseInt(numStr);
22	        const chineseMap = { "零":0, "一":1, "二":2, "三":3, "四":4, "五":5, "六":6, "七":7, "八":8, "九":9, "十":10 };
23	        if (numStr.length === 1) return chineseMap[numStr] || 999;
24	        if (numStr.startsWith("十")) return 10 + (chineseMap[numStr[1]] || 0);
25	        if (numStr.endsWith("十")) return (chineseMap[numStr[0]] || 0) * 10;
26	        return 999;
27	    }
